facts = {"bird(tweety)": "given", "penguin(pingu)": "given"}
rules = [  # (conditions, conclusion) for one variable X.
    (["bird(X)"], "animal(X)"),
    (["penguin(X)"], "bird(X)"),
    (["penguin(X)"], "not flies(X)"),
]

def forward_chain():
    changed = True
    while changed:
        changed = False
        for conds, concl in rules:
            for name in ("tweety", "pingu"):
                need = [c.replace("X", name) for c in conds]
                new = concl.replace("X", name)
                if all(n in facts for n in need) and new not in facts:
                    facts[new] = " + ".join(need) + " + rule"   # record the proof.
                    changed = True

def answer(q):
    if q in facts: return "entailed"
    if "not " + q in facts: return "contradicted"
    return "unknown"

forward_chain()
print(facts["animal(tweety)"])      # bird(tweety) + rule
print(answer("flies(pingu)"))       # contradicted
print(answer("flies(tweety)"))      # unknown
```

